head.script:
/* 프로그램ID */
scwin.pgmId = 'PGJ176F01';

/* 최상단의 선언 */
scwin.isMain = function() {
    return true;
}

/* 현장 조사 수수료 */
const spotExmnCmms = Number(70000);

/* 신문 공고료 */
const nwsprPbancChrg = Number(220000);



/**
 * 동산 계산결과후 재계산버튼 눌렀을시 화면 이동과 동시에 TAP을 동산 TAP으로 변경
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.18.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.onpageload = function() {

    /* 메뉴 */
    if(!scutilo.isEmpty(scwin.pgmId)){
        $p.main().wfm_side.scope.scwin.menuFocus(scwin.pgmId.slice(0,6));
    }

    var flagNo= $p.local.getItem("flagData");
    var retObj = JSON.parse(flagNo);
    if (retObj !=null) {
        var mvprpTapFlagNo = retObj.mvprpTapFlagNo;
        if (mvprpTapFlagNo == "1"){
            tac_auctnCst.setSelectedTabIndex(1);
            $p.local.removeItem("flagData");
        }
    }
};

scwin.onpageunload = function() {

};

/**
 * 특정 문자 제거
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.dsignCharFormat = function(amt){

    if (amt == null || amt == "") {
        return "";
    }
    var result = amt.replace(/\:/g, "");
    var result = result.replace(/\,/g, "");
    var result = result.replace(/\./g, "");
    return result;
}

/**
 * 금액 입력시 자동 컴마 찍기
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.cfComma = function(vVal, vNum){
    var tmpVal;
    var rtnVal;

    if(vNum == 1){
        tmpVal = scwin.dsignCharFormat(vVal);
    }else{
        tmpVal = vVal.toFixed(0);
    }

    if(tmpVal.length <= 3){
        rtnVal = tmpVal;
    }else if(tmpVal.length == 4){
        rtnVal = tmpVal.substring(0,1)+","+tmpVal.substring(1);
    }else if(tmpVal.length == 5){
        rtnVal = tmpVal.substring(0,2)+","+tmpVal.substring(2);
    }else if(tmpVal.length == 6){
        rtnVal = tmpVal.substring(0,3)+","+tmpVal.substring(3);
    }else if(tmpVal.length == 7){
        rtnVal = tmpVal.substring(0,1)+","+tmpVal.substring(1,4)+","+tmpVal.substring(4);
    }else if(tmpVal.length == 8){
        rtnVal = tmpVal.substring(0,2)+","+tmpVal.substring(2,5)+","+tmpVal.substring(5);
    }else if(tmpVal.length == 9){
        rtnVal = tmpVal.substring(0,3)+","+tmpVal.substring(3,6)+","+tmpVal.substring(6);
    }else if(tmpVal.length == 10){
        rtnVal = tmpVal.substring(0,1)+","+tmpVal.substring(1,4)+","+tmpVal.substring(4,7)+","+tmpVal.substring(7);
    }else if(tmpVal.length == 11){
        rtnVal = tmpVal.substring(0,2)+","+tmpVal.substring(2,5)+","+tmpVal.substring(5,8)+","+tmpVal.substring(8);
    }else if(tmpVal.length == 12){
        rtnVal = tmpVal.substring(0,3)+","+tmpVal.substring(3,6)+","+tmpVal.substring(6,9)+","+tmpVal.substring(9);
    }else if(tmpVal.length == 13){
        rtnVal = tmpVal.substring(0,1)+","+tmpVal.substring(1,4)+","+tmpVal.substring(4,7)+","+tmpVal.substring(7,10)+","+tmpVal.substring(10);
    }else if(tmpVal.length == 14){
        rtnVal = tmpVal.substring(0,2)+","+tmpVal.substring(2,5)+","+tmpVal.substring(5,8)+","+tmpVal.substring(8,11)+","+tmpVal.substring(11);
    }else if(tmpVal.length == 15){
        rtnVal = tmpVal.substring(0,3)+","+tmpVal.substring(3,6)+","+tmpVal.substring(6,9)+","+tmpVal.substring(9,12)+","+tmpVal.substring(12);
    }else {
        tmpVal = tmpVal.substring(tmpVal.length, tmpVal.length-15);
        rtnVal = tmpVal.substring(0,3)+","+tmpVal.substring(3,6)+","+tmpVal.substring(6,9)+","+tmpVal.substring(9,12)+","+tmpVal.substring(12);
    }
    return rtnVal;
}

/**
 * inputBox 문자 체크
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.checkNumber = function(inputType) {
  if(inputType.key >= 0 && inputType.key <= 9 || inputType.key == 'Enter') {
    return true;
  }
  return false;
}

/**
 * 금액 입력시 자동으로 세자리 컴마찍기
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.checkNumber_onkeyup = function(e) {

    /* 문자 체크 */
    var flag = scwin.checkNumber(e);
    if(flag){
        this.setValue(scwin.cfComma(this.getValue(),1));
    }else {
        this.setValue("");
    }
};

/**
 * 엔터키, 예상비용계산 클릭시 납부할 예납금 계산
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.iprpamtCalc_onkeydown = function(e) {
    let flag = 0;
    let checkID = this.getID();
    checkID = checkID.replace("mf_","");
    const key = e.key || e.code
    if (key == 'Enter') {
        if (checkID == "ibx_gnrlAeeAmt" || checkID == "btn_gnrlAeeCalcRslt") { /* 일반감정 예납금 계산 */
            scwin.gnrlAeePrpamt();
        } else if (checkID == "ibx_aptAeeAmt" || checkID == "btn_aptAeeCalcRslt") { /* 아파트감정 예납금 계산 */
            scwin.aptAeePrpamt();
        } else if (checkID == "ibx_rletEtcIntrpsCnt" || checkID == "btn_rletEtcExptDlvrfCalcRslt") { /* 부동산 등 예상송달료 계산 */
            var dsCntObj = ibx_rletEtcIntrpsCnt.getValue();
            var amtObj = ibx_rletEtcExptDlvrfPayDepst.getValue();
            flag = 1;
            scwin.exptDlvrf(dsCntObj, amtObj,flag);
        } else if (checkID == "ibx_carEtcAmt" || checkID == "btn_carEtcCalcRslt"){ /* 자동차 등 예납금 계산 */
            scwin.carPrpamtCalc();
        } else if (checkID == "ibx_carEtcIntrpsCnt" || checkID == "btn_carEtcExptDlvrfCalcRslt") { /* 자동차 등 예상송달료 계산 */
            var dsCntObj = ibx_carEtcIntrpsCnt.getValue();
            var amtObj = ibx_carEtcExptDlvrfPayDepst.getValue();
            flag = 2;
            scwin.exptDlvrf(dsCntObj, amtObj,flag);
        } else if (checkID == "ibx_etcAuctnAmt" || checkID == "btn_etcAuctnCalcRslt"){ /* 기타경매 예납금 계산 */
            scwin.etcAuctnPrpamtCalc();
        } else if (checkID == "ibx_etcAuctnIntrpsCnt" || checkID == "btn_etcAuctnExptDlvrfCalcRslt") { /* 기타경매 예상송달료 계산 */
            var dsCntObj = ibx_etcAuctnIntrpsCnt.getValue();
            var amtObj = ibx_etcAuctnExptDlvrfPayDepst.getValue();
            flag = 3;
            scwin.exptDlvrf(dsCntObj, amtObj,flag);
        }
    }
};




/**
 * 초기화 버튼 클릭 시 초기화
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.prpamtInizn_onclick = function(e) {
    var checkID = this.getID();
    checkID = checkID.replace("mf_","");
    if (checkID == "btn_gnrlAeeInizn") { /* 부동산 등 일반감정 예납금 초기화 */
        ibx_gnrlAeeAmt.setValue("");
        ibx_gnrlAeePayDepst.setValue("");
    } else if (checkID == "btn_aptAeeInizn") { /* 부동산 등 아파트감정 예납금 초기화 */
        ibx_aptAeeAmt.setValue("");
        ibx_aptAeePayDepst.setValue("");
    } else if (checkID == "btn_rletEtcExptDlvrfInizn") { /* 부동산 등 예상송달료 초기화 */
        ibx_rletEtcIntrpsCnt.setValue("");
        ibx_rletEtcExptDlvrfPayDepst.setValue("");
    } else if (checkID == "btn_carEtcInizn") { /* 자동차 등 예납금 초기화 */
        ibx_carEtcAmt.setValue("");
        ibx_carEtcPayDepst.setValue("");
    } else if (checkID == "btn_carEtcExptDlvrfInizn") { /* 자동차 등 예상송달료 초기화 */
        ibx_carEtcIntrpsCnt.setValue("");
        ibx_carEtcExptDlvrfPayDepst.setValue("");
    } else if (checkID == "btn_etcAuctnInizn") { /* 기타경매 예납급 초기화 */
        ibx_etcAuctnAmt.setValue("");
        ibx_etcAuctnPayDepst.setValue("");
    } else if (checkID == "btn_etcAuctnExptDlvrfInizn") { /* 기타경매 예상송달료 초기화 */
        ibx_etcAuctnIntrpsCnt.setValue("");
        ibx_etcAuctnExptDlvrfPayDepst.setValue("");
    }
};

/**
 * 일반 감정 예납금 계산
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.gnrlAeePrpamt = function(){
    var strAmt = ibx_gnrlAeeAmt.getValue();
    var amt = scwin.dsignCharFormat(strAmt);
    var resultAmt = 0;

    if(amt=="" || amt==null){
        scutilo.showMsg(scglblo.MSG.WARN,"예상매각대금을 입력하세요",()=>{
            ibx_gnrlAeeAmt.focus();
        });
        return
    }else if(isNaN(amt) || Number(amt) <= 0){
        scutilo.showMsg(scglblo.MSG.WARN,"예상매각대금을 올바르게 입력하세요",()=>{
            ibx_gnrlAeeAmt.focus();
        });
        return
    }else{
        amt = Number(amt);
        //감정료 계산
        if(amt <= 197727272){
            resultAmt = (290000 + 48000);
        }else if(amt > 197727272 && amt <= 200000000){
            resultAmt = (((((amt-50000000) *  0.0011) + 200000) * 0.8) + 48000);
        }else if(amt > 200000000 && amt <= 500000000){
            resultAmt = (((((amt-50000000) *  0.0011) + 200000) * 0.8) + 88000);
        }else if(amt > 500000000 && amt <= 1000000000){
            resultAmt = (((((amt-500000000) *  0.0009) + 695000) * 0.8) + 88000);
        }else if(amt > 1000000000 && amt <= 5000000000){
            resultAmt = (((((amt-1000000000) *  0.0008) + 1145000) * 0.8) + 88000);
        }else if(amt > 5000000000 && amt <= 10000000000){
            resultAmt = (((((amt-5000000000) *  0.0007) + 4345000) * 0.8) + 88000);
        }else if(amt > 10000000000 && amt <= 11925000000){
            resultAmt = (((((amt-10000000000) *  0.0006) + 7845000) * 0.8) + 88000);
        }else if(amt > 11925000000 ){
            resultAmt = (7200000 + 88000);
        }

        resultAmt = resultAmt + (resultAmt * 0.1) + spotExmnCmms + nwsprPbancChrg + scwin.dspslCmms(amt);
        ibx_gnrlAeePayDepst.setValue(resultAmt);
    }
}

/**
 * 아파트 감정 예납금 계산
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.aptAeePrpamt = function() {
    var strAmt = ibx_aptAeeAmt.getValue();
    var amt = scwin.dsignCharFormat(strAmt);
    var resultAmt = 0;

    if(amt=="" || amt==null){
        scutilo.showMsg(scglblo.MSG.WARN,"예상매각대금을 입력하세요",()=>{
            ibx_aptAeeAmt.focus();
        });
        return
    }else if(isNaN(amt) || Number(amt) <= 0){
        scutilo.showMsg(scglblo.MSG.WARN,"예상매각대금을 올바르게 입력하세요",()=>{
            ibx_aptAeeAmt.focus();
        });
        return
    }else{
        debugger
        amt = Number(amt);
        //감정료 계산
        if(amt <= 200000000){
            resultAmt = (290000 + 48000);
        }else if(amt > 200000000 && amt <= 244804545){
            resultAmt = (290000 + 88000);
        }else if(amt > 244804545 && amt <= 500000000){
            resultAmt = (((((amt - 50000000) * 0.0011) + 200000) * 0.7) + 88000);
        }else if(amt > 500000000 && amt <= 1000000000){
            resultAmt = (((((amt-500000000) *  0.0009) + 695000) * 0.7) + 88000);
        }else if(amt > 1000000000 && amt <= 5000000000){
            resultAmt = (((((amt-1000000000) *  0.0008) + 1145000) * 0.7) + 88000);
        }else if(amt > 5000000000 && amt <= 10000000000){
            resultAmt = (((((amt-5000000000) *  0.0007) + 4345000) * 0.7) + 88000);
        }else if(amt > 10000000000 && amt <= 14067856666){
            resultAmt = (((((amt-10000000000) *  0.0006) + 7845000) * 0.7) + 88000);
        }else if(amt > 14067856666 ){
            resultAmt = (7200000 + 88000);
        }

        // 부가가치세 추가
        // 현황조사 수수료 추가
        // 신문공료 추가
        // 매각수수료 추가
        resultAmt = resultAmt + (resultAmt * 0.1) + spotExmnCmms + nwsprPbancChrg + scwin.dspslCmms(amt);
        ibx_aptAeePayDepst.setValue(resultAmt);
    }
}

/**
 * 자동차예납금 계산
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.carPrpamtCalc = function(){
    var strAmt = ibx_carEtcAmt.getValue();
    var amt = scwin.dsignCharFormat(strAmt);
    var resultAmt = 0;

    if (amt=="" || amt==null) {
        scutilo.showMsg(scglblo.MSG.WARN,"예상매각대금을 입력하세요",()=>{
            ibx_carEtcCrtrAmt.focus();
        });
        return
    } else if(isNaN(amt) || Number(amt) <= 0) {
        scutilo.showMsg(scglblo.MSG.WARN,"예상매각대금을 올바르게 입력하세요",()=>{
            ibx_carEtcCrtrAmt.focus();
        });
        return
    } else {
        amt = Number(amt);
        //감정료 계산
        if(amt <= 5000000){
            resultAmt = (100000 + 48000);
        }else if(amt > 5000000 && amt <= 197727272){
            resultAmt = (290000 + 48000);
        }else if(amt > 197727272 && amt <= 200000000){
            resultAmt = (((((amt-50000000) *  0.0011) + 200000) * 0.8) + 48000);
        }else if(amt > 200000000 && amt <= 500000000){
            resultAmt = (((((amt-50000000) *  0.0011) + 200000) * 0.8) + 88000);
        }else if(amt > 500000000 && amt <= 1000000000){
            resultAmt = (((((amt-500000000) *  0.0009) + 695000) * 0.8) + 88000);
        }else if(amt > 1000000000 && amt <= 5000000000){
            resultAmt = (((((amt-1000000000) *  0.0008) + 1145000) * 0.8) + 88000);
        }else if(amt > 5000000000 && amt <= 10000000000){
            resultAmt = (((((amt-5000000000) *  0.0007) + 4345000) * 0.8) + 88000);
        }else if(amt > 10000000000 && amt <= 11925000000){
            resultAmt = (((((amt-10000000000) *  0.0006) + 7845000) * 0.8) + 88000);
        }else if(amt > 11925000000 ){
            resultAmt = (7200000 + 88000)
        }

        // 부가가치세 추가
        // 신문공료 추가
        // 매각수수료 추가
        resultAmt = resultAmt + (resultAmt * 0.1) + nwsprPbancChrg + scwin.dspslCmms(amt);
        ibx_carEtcPayDepst.setValue(resultAmt);
    }
}

