/**
 * 매각 수수료
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 * ============= ============ ==========================
 */
scwin.dspslCmms = function(gnrlAeeAmt){
    var aeeAmt = 0;
    if(gnrlAeeAmt <= 100000) {
        aeeAmt = 5000;
    }else if(gnrlAeeAmt > 100000 && gnrlAeeAmt <= 10000000){
        aeeAmt = ((gnrlAeeAmt - 100000) * 0.02) + 5000;
    }else if(gnrlAeeAmt > 10000000 && gnrlAeeAmt <= 50000000){
        aeeAmt = ((gnrlAeeAmt - 10000000) * 0.015) + 203000;
    }else if(gnrlAeeAmt > 50000000 && gnrlAeeAmt <= 100000000){
        aeeAmt = ((gnrlAeeAmt - 50000000) * 0.01) + 803000;
    }else if(gnrlAeeAmt > 100000000 && gnrlAeeAmt <= 300000000){
        aeeAmt = ((gnrlAeeAmt - 100000000) * 0.005) + 1303000;
    }else if(gnrlAeeAmt > 300000000 && gnrlAeeAmt <= 500000000){
        aeeAmt = ((gnrlAeeAmt - 300000000) * 0.003) + 2303000;
    }else if(gnrlAeeAmt > 500000000 && gnrlAeeAmt <= 1000000000){
        aeeAmt = ((gnrlAeeAmt - 500000000) * 0.002) + 2903000;
    }else if(gnrlAeeAmt > 1000000000) {
        aeeAmt = 3903000;
    }

    return aeeAmt;
}

/**
 * 예상 송달료 계산
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.08.09.   나해준       [NELS]최초 생성
 *  2025.05.30.   강은숙       [25A-PGJ-0007] 송달료 5,200 -> 5,500원 수정
 *  2026.06.30.   강은숙       [26A-PGJ-0028] 경매비용 송달료 5,640원 인상 적용(5,500원 -> 5,640원)
 * ============= ============ ==========================
 */
scwin.exptDlvrf = function(dsCntObj, amtObj,flag){
    const dlvrfOneChrg = 5640;
    var sdAmt = 0;

    if(dsCntObj =="" || dsCntObj==null){
        scutilo.showMsg(scglblo.MSG.WARN,"이해관계인 수 를 입력하세요",()=>{
            ibx_intrpsCnt.focus();
        });
        return;
    }else if(isNaN(dsCntObj) || Number(dsCntObj) <= 0){
        scutilo.showMsg(scglblo.MSG.WARN,"이해관계인 수 를 올바르게입력하세요",()=>{
            ibx_intrpsCnt.focus();
        });
        return;
    }

    if(dsCntObj != null && amtObj != null && Number(dsCntObj) > 0){
        sdAmt = (Number(dsCntObj) + 3) * (10 * dlvrfOneChrg);
    }else{
        return;
    }

    if (flag == 1) {
        /* 부동산 등 예상송달료 */
        ibx_rletEtcExptDlvrfPayDepst.setValue(sdAmt);
    } else if (flag == 2) {
        /* 자동차 등 예상송달료 */
        ibx_carEtcExptDlvrfPayDepst.setValue(sdAmt);
    } else if (flag == 3) {
        /* 기타경매 예상송달료 */
        ibx_etcAuctnExptDlvrfPayDepst.setValue(sdAmt)
    }
}

